-- Wikimedia Commons licensed model-year photography: exact manufacturer/model,
-- source credit and license. Gallery-only: never replace the approved hero.
-- Model-year is not guessed from the date when a photograph was taken.
with approved(asset_key,manufacturer,model,model_year_start,subject_category,title,image_url,source_page_url,photographer,licence,licence_url,attribution,review_notes) as (values
('gallery-honda-cb500x-2019-lancia-dude','Honda','CB500X',2019,'whole_motorcycle','2019 Honda CB500X — white and yellow edition','https://commons.wikimedia.org/wiki/Special:FilePath/2019%20Honda%20CB500X.jpg?width=1280','https://commons.wikimedia.org/wiki/File:2019%20Honda%20CB500X.jpg','Lancia Dude','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Lancia Dude · CC BY-SA 4.0','Commons author identifies subject explicitly as 2019 CB500X, uploaded 2022; subject model-year 2019, NOT year photo was taken; not a factory paint code verification.'),
('gallery-honda-cb500x-2021-chanokchon','Honda','CB500X',2021,'whole_motorcycle','2021 Honda CB500X — documented motorcycle photograph','https://commons.wikimedia.org/wiki/Special:FilePath/2021%20Honda%20CB500X.jpg?width=1280','https://commons.wikimedia.org/wiki/File:2021%20Honda%20CB500X.jpg','Chanokchon','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Chanokchon · CC BY-SA 4.0','Commons caption states 2021 Honda CB500X; year is subject descriptor, not proof of manufacturing plate year; verify exact market and equipment.'),
('gallery-kawasaki-ninja650-kidfly182-2024','Kawasaki','Ninja 650',NULL,'whole_motorcycle','Kawasaki Ninja 650 photographed in Manhattan in 2024','https://commons.wikimedia.org/wiki/Special:FilePath/Kawasaki%20Ninja%20650%20003.jpg?width=1280','https://commons.wikimedia.org/wiki/File:Kawasaki%20Ninja%20650%20003.jpg','Kidfly182','CC BY 4.0','https://creativecommons.org/licenses/by/4.0/','Kidfly182 · CC BY 4.0','Photo taken 5 October 2024 in Manhattan. This is photograph date only; vehicle model year is unconfirmed, so model_year_start stays null.')
)
insert into public.anybike_editorial_photo_bank(asset_key,manufacturer,model,model_year_start,subject_category,title,image_url,source_page_url,photographer,licence,licence_url,attribution,approval_status,reviewed_at,review_notes,source_type,usage_contexts,feature_tags)
select p.asset_key,p.manufacturer,p.model,p.model_year_start,p.subject_category,p.title,p.image_url,p.source_page_url,p.photographer,p.licence,p.licence_url,p.attribution,'approved',now(),p.review_notes,'external_reference',array['model_variant_gallery'],array['exact_model','documented_gallery']
from approved p
where exists(select 1 from public.motorcycle_catalog_models m where m.manufacturer=p.manufacturer and m.model=p.model)
on conflict(asset_key) do nothing;